<script setup lang="ts">
import {readableApiError} from '../../api/client'
import { onMounted, reactive, ref } from 'vue'
import { api, ApiError } from '../../api/client'
type School={id:number;name:string;campuses:{id:number;name:string}[]}
const school=ref<School|null>(null),campusId=ref(0),sending=ref(false),error=ref(''),success=ref('')
const form=reactive({organization_name:'',applicant_name:'',official_email:'',contact_phone:'',intended_locations:'',evidence_url:'',statement:''})
onMounted(async()=>{const campus=localStorage.getItem('campustrace-campus')??'';campusId.value=Number(campus);try{const response=await api<{data:{schools:School[]}}>(`/stations/campuses/?current_campus=${encodeURIComponent(campus)}`);school.value=response.data.schools[0]??null}catch{error.value='无法读取当前学校资料'}})
async function submit(){if(!school.value)return;sending.value=true;error.value='';try{await api('/stations/station-applications/',{method:'POST',body:JSON.stringify({...form,school:school.value.id,campus:campusId.value})});success.value='申请已提交。平台将核对官方邮箱、证明链接和经办人身份。'}catch(reason){error.value=readableApiError(reason,'提交失败')}finally{sending.value=false}}
</script>
<template><div class="page"><header><h1 class="page-title">学校官方接入</h1><p class="page-lead">{{school?.name??'当前学校'}} · 申请人应为保卫、学工、宿管或学生服务等有权部门的经办人。</p></header><form class="panel form" @submit.prevent="submit"><label>学校/部门名称<input v-model="form.organization_name" required/></label><label>经办人姓名<input v-model="form.applicant_name" required/></label><label>学校官方邮箱<input v-model="form.official_email" type="email" required/></label><label>联系电话<input v-model="form.contact_phone" required/></label><label class="wide">拟设站点与位置<textarea v-model="form.intended_locations" required placeholder="例如：保卫处一楼、学生服务中心"/></label><label class="wide">学校官网证明链接<input v-model="form.evidence_url" type="url" required placeholder="https://..."/></label><label class="wide">授权与运营说明<textarea v-model="form.statement" required placeholder="说明经办人职责、物品保管能力和开放时间"/></label><p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p><button class="button button-brand" :disabled="sending||Boolean(success)">{{sending?'提交中…':'提交身份核验申请'}}</button></form></div></template>
<style scoped>.form{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:32px;padding:28px}.form label{display:grid;gap:7px;color:var(--ct-text-muted);font-size:12px}.form input,.form textarea{padding:12px;border:1px solid var(--ct-border);border-radius:9px;background:var(--ct-bg-soft);color:var(--ct-text)}.form textarea{min-height:100px}.wide{grid-column:1/-1}.form>.button,.notice{grid-column:1/-1}.notice{padding:12px}.error{color:var(--ct-danger);background:#ad343412}.success{color:var(--ct-success);background:#36644b12}@media(max-width:620px){.form{grid-template-columns:1fr}.wide,.form>.button,.notice{grid-column:auto}}</style>
